### Step 6: Implement `SwissEphFile` in `src/sweph_file/mod.rs`

```rust
mod parse;
pub mod types;

use std::path::Path;
use memmap2::Mmap;
use crate::error::Error;
use crate::types::Body;
pub use types::{FileHeader, PlanetFileData, FileType, ByteOrder};

pub struct SwissEphFile {
    mmap: Mmap,
    header: FileHeader,
    planets: Vec<PlanetFileData>,
}

impl SwissEphFile {
    pub fn open(path: &Path) -> Result<Self, Error> {
        let file = std::fs::File::open(path)
            .map_err(|_| Error::FileNotFound(path.to_path_buf()))?;
        // SAFETY: we treat the file as read-only and immutable
        let mmap = unsafe { Mmap::map(&file) }
            .map_err(|e| Error::FileFormat(format!("mmap failed: {e}")))?;
        let (header, offset) = parse::parse_header(&mmap)?;
        let planets = parse::parse_all_planets(
            &mmap, offset, /* npl from header */, header.byte_order,
        )?;
        Ok(Self { mmap, header, planets })
    }

    pub fn header(&self) -> &FileHeader { &self.header }

    pub fn planet_data(&self, body_id: i32) -> Option<&PlanetFileData> {
        self.planets.iter().find(|p| p.body_id == body_id)
    }

    /// Raw file bytes — needed by swisseph-rs/38 for coefficient unpacking
    pub fn bytes(&self) -> &[u8] { &self.mmap }
}

/// Map public Body enum to internal SEI body ID.
/// Returns None for bodies not stored in SE1 files.
pub fn sei_body_id(body: Body) -> Option<i32> {
    match body {
        Body::Sun => Some(types::SEI_SUN),
        Body::Moon => Some(types::SEI_MOON),
        Body::Mercury => Some(types::SEI_MERCURY),
        Body::Venus => Some(types::SEI_VENUS),
        Body::Mars => Some(types::SEI_MARS),
        Body::Jupiter => Some(types::SEI_JUPITER),
        Body::Saturn => Some(types::SEI_SATURN),
        Body::Uranus => Some(types::SEI_URANUS),
        Body::Neptune => Some(types::SEI_NEPTUNE),
        Body::Pluto => Some(types::SEI_PLUTO),
        Body::Earth => Some(types::SEI_EARTH),
        // EMB if needed
        _ => None,
    }
}
```

`SwissEphFile` is `Send + Sync` automatically since `Mmap` is `Send + Sync`, `FileHeader` owns only `String` (Send+Sync), and `Vec<PlanetFileData>` is Send+Sync (all fields are Copy primitives).

### Step 7: Write C golden-data harness (`tests/c-gen/gen_se1_header.c`)

A C program that:
1. Calls `swe_set_ephe_path("../../swisseph/ephe")` to initialize
2. Forces Swiss Eph mode (SEFLG_SWIEPH) and triggers file loading by calling `swe_calc` for a planet
3. Reaches into internal `swed.fidat[]` and `swed.pldat[]` to extract header and per-planet metadata
4. Dumps as JSON matching the golden test schema:

```json
{
  "files": [
    {
      "filename": "sepl_18.se1",
      "version": "...",
      "file_type": "planet",
      "tfstart": ..., "tfend": ...,
      "denum": 431,
      "byte_order": "little",
      "planets": [
        {
          "body_id": 0, "iflg": 0, "ncoe": ..., "neval": ...,
          "rmax": ..., "dseg": ..., "tfstart": ..., "tfend": ...,
          "lndx0": ..., "nndx": ...,
          "prot": 0.0, "qrot": 0.0, "dprot": 0.0, "dqrot": 0.0,
          "peri": 0.0, "dperi": 0.0
        },
        ...
      ]
    },
    { "filename": "semo_18.se1", ... }
  ]
}
```

Compile: `gcc gen_se1_header.c -I../../swisseph -L../../swisseph -lswe -lm -o gen_se1_header`
Run: `./gen_se1_header > ../golden-data/se1_header.json`

Note: accessing `swed` internals requires `#include "sweph.h"` and `extern struct swe_data swed;`.

### Step 8: Write golden tests (`tests/golden/se1_header.rs`)

```rust
use serde::Deserialize;
use swisseph::sweph_file::{SwissEphFile, FileType};
use std::path::PathBuf;

#[derive(Deserialize)]
struct PlanetCase {
    body_id: i32,
    iflg: u32,
    ncoe: usize,
    neval: usize,
    rmax: f64,
    dseg: f64,
    tfstart: f64,
    tfend: f64,
    lndx0: usize,
    nndx: usize,
    prot: f64, qrot: f64, dprot: f64, dqrot: f64,
    peri: f64, dperi: f64,
}

#[derive(Deserialize)]
struct FileCase {
    filename: String,
    version: String,
    file_type: String,
    tfstart: f64, tfend: f64,
    denum: i32,
    byte_order: String,
    planets: Vec<PlanetCase>,
}

#[derive(Deserialize)]
struct GoldenData { files: Vec<FileCase> }

fn ephe_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("swisseph")
        .join("ephe")
        .join(name)
}

#[test]
fn header_fields_match_c() {
    let data: GoldenData = serde_json::from_str(
        &std::fs::read_to_string(super::golden_data_path("se1_header.json")).unwrap()
    ).unwrap();

    for file_case in &data.files {
        let eph = SwissEphFile::open(&ephe_path(&file_case.filename)).unwrap();
        let h = eph.header();

        assert_eq!(h.version, file_case.version);
        super::assert_f64_exact("tfstart", file_case.tfstart, h.time_range.0);
        super::assert_f64_exact("tfend", file_case.tfend, h.time_range.1);
        assert_eq!(h.denum, file_case.denum);

        for pc in &file_case.planets {
            let pd = eph.planet_data(pc.body_id)
                .unwrap_or_else(|| panic!("missing body_id {} in {}", pc.body_id, file_case.filename));
            assert_eq!(pd.iflg, pc.iflg);
            assert_eq!(pd.ncoe, pc.ncoe);
            assert_eq!(pd.neval, pc.neval);
            super::assert_f64_exact("rmax", pc.rmax, pd.rmax);
            super::assert_f64_exact("dseg", pc.dseg, pd.dseg);
            super::assert_f64_exact("tfstart", pc.tfstart, pd.tfstart);
            super::assert_f64_exact("tfend", pc.tfend, pd.tfend);
            assert_eq!(pd.lndx0, pc.lndx0);
            assert_eq!(pd.nndx, pc.nndx);
            super::assert_f64_exact("prot", pc.prot, pd.prot);
            super::assert_f64_exact("qrot", pc.qrot, pd.qrot);
            super::assert_f64_exact("dprot", pc.dprot, pd.dprot);
            super::assert_f64_exact("dqrot", pc.dqrot, pd.dqrot);
            super::assert_f64_exact("peri", pc.peri, pd.peri);
            super::assert_f64_exact("dperi", pc.dperi, pd.dperi);
        }
    }
}

#[test]
fn byte_order_detection_all_files() {
    // Open every .se1 file in ephe/ to verify byte-order detection doesn't panic
    let ephe_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("swisseph")
        .join("ephe");
    for entry in std::fs::read_dir(&ephe_dir).unwrap() {
        let path = entry.unwrap().path();
        if path.extension().is_some_and(|e| e == "se1") {
            SwissEphFile::open(&path).unwrap_or_else(|e| {
                panic!("failed to open {}: {e}", path.display())
            });
        }
    }
}
